    def lexicographically_larger_than_shifted(s, length):
        i = length - 1
        if i == 0:
            return True
        for j in range(i-1, 0, -1):
            if s[j] > s[i]:
                i -= 1
            elif s[i] > s[j]:
                return False
        return True

    def shift_and_compare(s, length):
        if lexicographically_larger_than_shifted(s, length):
            return True
        return False

    def naive_search(s, d):
        len_s = len(s)
        for i in range(len(s, len_s - d + 1)):
            if len(set(s[i:i+d])) != d and shift_and_compare(s[i:i+d], len(s, d)):
                return True
        return False

    def binary_search(s, d):
        lo, hi = 0, len(str(s[0]))
        while lo < hi - 1:
            mid = (lo + hi) // 2
