def max_beauty_brackets(n, brackets):
    total_beauty = 0
    balance = 0

    for i, bracket in enumerate(brackets):
        if bracket == '(':
            balance += 1
        else:
            balance -= 1
        total_beauty += balance

    if balance != 0:
        return 0, (n, 1)

    max_beauty = 0
    pairs = []
    current_uneven = 0
    for i, bracket in enumerate(brackets):
        if i - 1 >= 0 and brackets[i - 1] == '(' and bracket == ')':
            current_uneven += 1
        if i - 1 >= 0 and brackets[i - 1] == ')' and bracket == '(':
            current_uneven -= 1

        if current_uneven * 2 > (i + 1) / 2:
            pairs.append((i // 2, (i + 1) // 2))
            if current_uneven * 2 != (i + 1) / 2:
                current_uneven = 0
                total_beauty -= 1

        if i - 1 >= 0 and brackets[i - 1] == '(' and bracket == ')':
            current_uneven -= 1
        if i - 1 >= 0 and brackets[i - 1] == ')' and bracket == '(':
            current_uneven += 1

    max_i, max_j = pairs[0]
    if len(pairs) > 1:
        pairs.append((max_i - 1, max_j + 1))
    for i, j in pairs:
        total_beauty += 1 - (1 - i) * (1 - j)

    return max(total_beauty, 0), (max_i // 2, max_j // 2) + (1 - max_i) * (1 - max_j)

