        # Check in all possible orientations of the car position
        for dx in [-1, 0, 1]:
            for dy in [-1, 0, 1]:
                if 0 <= x + dx <= len(rows) and 0 <= y + dy <= len(columns) and rows[x + dx][y + dy] == 'X':
                    max_side = max(max_side, get_max_square_size(rows, columns, [(x, y), (x + dx, y + dy)]))
        if x == 0:
            rows[0], rows[1], rows[2] = [row[2:] for row in rows]
        elif x == len(rows) - 1:
            rows[x-1], rows[x], rows[x+1] = [row[:-1] for row in rows]
        else:
            rows[x-1], rows[x], rows[x+1] = [row[:-1] for row in rows]
            rows[x], rows[x+1] = [row[1:] for row in rows[x:]]
        max_side = max(max_side, get_max_square_size(rows, columns, [(x, y)]))
    return max_side

if __name__ == "__main__":
    n, m, k = map(int, input().split())
    parking_lot = [input().strip() for _ in range(n)]
    car_positions = []
    for _ in range(k):
        x, y = map(int, input().split())
        car_positions.append((x - 1, y - 1))  # Convert to 0-based index

    print(get_max_square_size(parking_lot, [parking_lot[0][:y], parking_lot[0][y+1:], parking_lot[1][:x], parking_lot[1][x:]], car_positions))
