from collections import defaultdict

def find_ways(a, b, c, d, k):
    ways = defaultdict(int)
    MOD = 1000000007
    directions = [(-1, 0), (0, -1), (1, 0), (0, 1)]

    for x, y in products(range(a, c + 1), range(b, d + 1)):
        if x + y + k == c + d:
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                ways[(nx, ny)] += 1

    return sum(ways.values()) % MOD

def main():
    T = int(input())
    for _ in range(T):
        N, K = map(int, input().split())
        print(find_ways(0, 1, K, N, K))

if __name__ == "__main__":
    main()
