def is_good(s, d, i):
    for j in range(i, d):
        if (s[i] != s[j]):
            if (s[(i + j) // 2 % len(s)] != s[~(i + j) // 2 % len(s)]):
                return False
    return True

def find_next_good(s, d):
    if len(s) == 1:
        return s
    for i in range(len(s), 0, -1):
        if is_good(s, i, i):
            return s[:i-1] + find_next_good(s[i:], i)
    return "Impossible"

